css:
.bar {
  display: flex;
  gap: 8px;
  max-width: 420px;
  padding: 12px;
  border: 2px dashed #a1a1aa;
}

.field {
  flex-grow: 1;
  padding: 8px 12px;
  background: #fff;
  border: 1px solid #a1a1aa;
  border-radius: 6px;
  color: #71717a;
}

.go {
  flex-shrink: 0; /* keep the label whole */
  padding: 8px 14px;
  border: 0;
  border-radius: 6px;
  background: #f97316;
  color: #fff;
}
